// Resolution-independent game artwork and a fixed trail for smooth turns.
export function drawBaseball(c,x,y,r){c.save();c.translate(x,y);c.rotate(-.25);c.fillStyle='#fffdf6';c.strokeStyle='#465d79';c.lineWidth=r*.14;c.beginPath();c.arc(0,0,r,0,Math.PI*2);c.fill();c.stroke();c.strokeStyle='#d7475d';c.lineWidth=r*.11;c.lineCap='round';for(const side of [-1,1]){c.beginPath();c.moveTo(side*r*.68,-r*.7);c.bezierCurveTo(side*r*.2,-r*.25,side*r*.2,r*.25,side*r*.68,r*.7);c.stroke();for(let i=-2;i<=2;i++){const yy=i*r*.23,xx=side*r*(.33+.35*(yy/r)**2);c.beginPath();c.moveTo(xx-r*.1,yy-r*.07);c.lineTo(xx+r*.1,yy+r*.04);c.stroke();}}c.restore();}
export function drawSnakeHead(c,x,y,r,direction='right',blink=false){c.save();c.translate(x,y);c.rotate(typeof direction==='number'?direction:({right:0,down:Math.PI/2,left:Math.PI,up:-Math.PI/2})[direction]);c.fillStyle='#5276e7';c.beginPath();c.roundRect(-r,-r*.78,r*2.15,r*1.56,r*.7);c.fill();for(const side of [-1,1]){c.fillStyle='#5276e7';c.beginPath();c.arc(r*.05,side*r*.73,r*.43,0,Math.PI*2);c.fill();c.fillStyle='#fff';c.beginPath();c.ellipse(r*.09,side*r*.74,r*.33,blink?r*.08:r*.34,0,0,Math.PI*2);c.fill();c.fillStyle='#223b78';c.beginPath();c.ellipse(r*.21,side*r*.74,r*.14,blink?r*.025:r*.19,0,0,Math.PI*2);c.fill();if(!blink){c.fillStyle='#fff';c.beginPath();c.arc(r*.24,side*r*.74-r*.07,r*.04,0,Math.PI*2);c.fill();}}c.fillStyle='#2d4eae';for(const side of [-1,1]){c.beginPath();c.ellipse(r*.83,side*r*.19,r*.04,r*.065,0,0,Math.PI*2);c.fill();}c.strokeStyle='#2f52b3';c.lineWidth=r*.055;c.lineCap='round';c.beginPath();c.moveTo(r*.44,r*.42);c.quadraticCurveTo(r*.8,r*.53,r*1.02,r*.28);c.stroke();c.restore();}
export function snakeTrail(game,progress=1){
 const p=Math.max(0,Math.min(1,progress)),body=game.body,previous=game.previous;
 if(!previous?.length||body[0].x===previous[0].x&&body[0].y===previous[0].y)return {points:body,angle:({right:0,down:Math.PI/2,left:Math.PI,up:-Math.PI/2})[game.direction]};
 const lerp=(a,b)=>({x:a.x+(b.x-a.x)*p,y:a.y+(b.y-a.y)*p}),points=[lerp(previous[0],body[0]),...body.slice(1)];
 // Keep every bend at its grid location. Only the two ends slide along the trail.
 if(body.length===previous.length)points.push(lerp(previous.at(-1),body.at(-1)));
 const fixed=points.filter((point,i)=>!i||point.x!==points[i-1].x||point.y!==points[i-1].y),from=Math.atan2(previous[0].y-previous[1].y,previous[0].x-previous[1].x),to=Math.atan2(body[0].y-previous[0].y,body[0].x-previous[0].x),delta=Math.atan2(Math.sin(to-from),Math.cos(to-from)),turn=Math.min(1,p*1.5),ease=turn*turn*(3-2*turn);
 return {points:fixed,angle:from+delta*ease};
}
export function traceSnakeTrail(c,points,cell){
 const xy=p=>({x:(p.x+.5)*cell,y:(p.y+.5)*cell}),path=points.map(xy);c.beginPath();c.moveTo(path[0].x,path[0].y);
 for(let i=1;i<path.length-1;i++){const a=path[i-1],b=path[i],d=path[i+1],ab=Math.hypot(b.x-a.x,b.y-a.y),bd=Math.hypot(d.x-b.x,d.y-b.y);if(!ab||!bd)continue;if((b.x-a.x)*(d.y-b.y)===(b.y-a.y)*(d.x-b.x))continue;const radius=Math.min(cell*.28,ab/2,bd/2);c.lineTo(b.x+(a.x-b.x)*radius/ab,b.y+(a.y-b.y)*radius/ab);c.quadraticCurveTo(b.x,b.y,b.x+(d.x-b.x)*radius/bd,b.y+(d.y-b.y)*radius/bd);}
 const tail=path.at(-1);c.lineTo(tail.x,tail.y);
}
export function drawSnakeScene(c,game,{width,height,progress=1,now=0}={}){const cell=Math.min(width,height)/20,padX=(width-cell*20)/2,padY=(height-cell*20)/2;c.clearRect(0,0,width,height);c.fillStyle='#eff5f3';c.fillRect(0,0,width,height);c.save();c.translate(padX,padY);c.fillStyle='#e3eeeb';for(let y=0;y<20;y++)for(let x=0;x<20;x++)if((x+y)%2===0)c.fillRect(x*cell,y*cell,cell,cell);
 if(game.food){const f=game.food,pulse=1+Math.sin(now/250)*.025;c.fillStyle='#ebc46d55';c.beginPath();c.arc((f.x+.5)*cell,(f.y+.5)*cell,cell*.57,0,Math.PI*2);c.fill();c.fillStyle='#253d5b24';c.beginPath();c.ellipse((f.x+.5)*cell,(f.y+.82)*cell,cell*.35,cell*.11,0,0,Math.PI*2);c.fill();drawBaseball(c,(f.x+.5)*cell,(f.y+.5)*cell,cell*.44*pulse);}
 const {points,angle}=snakeTrail(game,progress);c.strokeStyle='#5276e7';c.lineWidth=cell*.77;c.lineCap='round';c.lineJoin='round';traceSnakeTrail(c,points,cell);c.stroke();drawSnakeHead(c,(points[0].x+.5)*cell,(points[0].y+.5)*cell,cell*.54,angle,now%3800>3650);c.restore();}
